from pathlib import Path

path = Path("app/src/main/java/com/mixtervee/fastmagnifier/ScreenMagnifierService.kt")
text = path.read_text(encoding="utf-8")

# State for the minimized floating restore button.
old_fields = '''    private var lensParams: WindowManager.LayoutParams? = null\n    private var copyPopupView: View? = null\n'''
new_fields = '''    private var lensParams: WindowManager.LayoutParams? = null\n    private var copyPopupView: View? = null\n    private var minimizedView: View? = null\n    private var minimizedParams: WindowManager.LayoutParams? = null\n    private var magnifierMinimized = false\n    private var miniDragging = false\n    private var miniDownRawX = 0f\n    private var miniDownRawY = 0f\n    private var miniStartX = 0\n    private var miniStartY = 0\n    private var miniLastX = -1\n    private var miniLastY = -1\n'''
if old_fields not in text:
    raise SystemExit("Could not find magnifier view fields")
text = text.replace(old_fields, new_fields, 1)

# Clean up the minimized button as part of every normal stop/exit.
old_stop_state = '''        copyInProgress = false\n        dragging = false\n        longPressTriggered = false\n        mainHandler.removeCallbacks(refreshRunnable)\n'''
new_stop_state = '''        copyInProgress = false\n        dragging = false\n        longPressTriggered = false\n        magnifierMinimized = false\n        miniDragging = false\n        mainHandler.removeCallbacks(refreshRunnable)\n'''
if old_stop_state not in text:
    raise SystemExit("Could not find stop state block")
text = text.replace(old_stop_state, new_stop_state, 1)

old_remove = '''        if (::windowManager.isInitialized) {\n            lensView?.let { removeOverlay(it) }\n            copyPopupView?.let { removeOverlay(it) }\n        }\n'''
new_remove = '''        if (::windowManager.isInitialized) {\n            lensView?.let { removeOverlay(it) }\n            copyPopupView?.let { removeOverlay(it) }\n            minimizedView?.let { removeOverlay(it) }\n        }\n'''
if old_remove not in text:
    raise SystemExit("Could not find overlay cleanup block")
text = text.replace(old_remove, new_remove, 1)

old_nulls = '''        lensParams = null\n        copyPopupView = null\n\n        val old = lastWindowBitmap\n'''
new_nulls = '''        lensParams = null\n        copyPopupView = null\n        minimizedView = null\n        minimizedParams = null\n\n        val old = lastWindowBitmap\n'''
if old_nulls not in text:
    raise SystemExit("Could not find overlay null block")
text = text.replace(old_nulls, new_nulls, 1)

# Add a compact Min button without making the already-busy control row much wider.
old_controls = '''        controls.addView(controlButton("+") { changeScale(SCALE_STEP) })\n        controls.addView(controlButton("Back") { returnToMainMenu() })\n        controls.addView(controlButton("Exit") { exitApplication() })\n'''
new_controls = '''        controls.addView(controlButton("+") { changeScale(SCALE_STEP) })\n        controls.addView(\n            controlButton("Min") { minimizeScreenMagnifier() }.apply {\n                textSize = 12f\n                setPadding(dp(6), 0, dp(6), 0)\n            }\n        )\n        controls.addView(controlButton("Back") { returnToMainMenu() })\n        controls.addView(controlButton("Exit") { exitApplication() })\n'''
if old_controls not in text:
    raise SystemExit("Could not find screen magnifier control buttons")
text = text.replace(old_controls, new_controls, 1)

marker = '''    private fun returnToMainMenu() {'''
methods = '''    private fun minimizeScreenMagnifier() {\n        if (!magnifierRunning || magnifierMinimized) return\n\n        magnifierMinimized = true\n        refreshEnabled = false\n        mainHandler.removeCallbacks(refreshRunnable)\n        mainHandler.removeCallbacks(longPressRunnable)\n\n        copyPopupView?.let { removeOverlay(it) }\n        copyPopupView = null\n        lensView?.let { removeOverlay(it) }\n\n        if (!showMinimizedBubble()) {\n            // If Android refuses the small overlay, put the full lens back rather\n            // than leaving the user with no way to restore it.\n            magnifierMinimized = false\n            val lens = lensView\n            val params = lensParams\n            if (lens != null && params != null && !lens.isAttachedToWindow) {\n                runCatching { windowManager.addView(lens, params) }\n            }\n            startRefreshing()\n            Toast.makeText(this, "Could not minimize magnifier", Toast.LENGTH_SHORT).show()\n        }\n    }\n\n    private fun showMinimizedBubble(): Boolean {\n        minimizedView?.let { removeOverlay(it) }\n        minimizedView = null\n        minimizedParams = null\n\n        val metrics = resources.displayMetrics\n        val size = dp(58)\n        val margin = dp(10)\n\n        val bubble = TextView(this).apply {\n            text = "🔍"\n            textSize = 25f\n            gravity = Gravity.CENTER\n            setTextColor(Color.WHITE)\n            contentDescription = "Restore screen magnifier"\n            background = GradientDrawable().apply {\n                shape = GradientDrawable.RECTANGLE\n                setColor(Color.argb(242, 15, 18, 24))\n                setStroke(dp(3), CYAN)\n                cornerRadius = dp(17).toFloat()\n            }\n            elevation = dp(8).toFloat()\n            setOnTouchListener { _, event -> handleMinimizedTouch(event) }\n        }\n\n        val maxX = max(0, metrics.widthPixels - size)\n        val maxY = max(0, metrics.heightPixels - size)\n        val startX = if (miniLastX >= 0) miniLastX.coerceIn(0, maxX)\n            else (metrics.widthPixels - size - margin).coerceAtLeast(0)\n        val startY = if (miniLastY >= 0) miniLastY.coerceIn(0, maxY)\n            else (metrics.heightPixels / 3).coerceIn(0, maxY)\n\n        val params = WindowManager.LayoutParams(\n            size,\n            size,\n            WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,\n            WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or\n                WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,\n            PixelFormat.TRANSLUCENT\n        ).apply {\n            gravity = Gravity.TOP or Gravity.START\n            x = startX\n            y = startY\n        }\n\n        return try {\n            windowManager.addView(bubble, params)\n            minimizedView = bubble\n            minimizedParams = params\n            miniLastX = params.x\n            miniLastY = params.y\n            true\n        } catch (_: Throwable) {\n            false\n        }\n    }\n\n    private fun handleMinimizedTouch(event: MotionEvent): Boolean {\n        val bubble = minimizedView ?: return false\n        val params = minimizedParams ?: return false\n        val metrics = resources.displayMetrics\n\n        when (event.actionMasked) {\n            MotionEvent.ACTION_DOWN -> {\n                miniDownRawX = event.rawX\n                miniDownRawY = event.rawY\n                miniStartX = params.x\n                miniStartY = params.y\n                miniDragging = false\n                return true\n            }\n\n            MotionEvent.ACTION_MOVE -> {\n                val dx = event.rawX - miniDownRawX\n                val dy = event.rawY - miniDownRawY\n                val movement = hypot(dx.toDouble(), dy.toDouble()).toFloat()\n                if (!miniDragging && movement > touchSlop) miniDragging = true\n\n                if (miniDragging) {\n                    val maxX = max(0, metrics.widthPixels - bubble.width.coerceAtLeast(dp(58)))\n                    val maxY = max(0, metrics.heightPixels - bubble.height.coerceAtLeast(dp(58)))\n                    params.x = (miniStartX + dx.toInt()).coerceIn(0, maxX)\n                    params.y = (miniStartY + dy.toInt()).coerceIn(0, maxY)\n                    miniLastX = params.x\n                    miniLastY = params.y\n                    runCatching { windowManager.updateViewLayout(bubble, params) }\n                }\n                return true\n            }\n\n            MotionEvent.ACTION_UP -> {\n                val wasDragging = miniDragging\n                miniDragging = false\n                if (!wasDragging) restoreScreenMagnifier()\n                return true\n            }\n\n            MotionEvent.ACTION_CANCEL -> {\n                miniDragging = false\n                return true\n            }\n        }\n        return true\n    }\n\n    private fun restoreScreenMagnifier() {\n        if (!magnifierRunning || !magnifierMinimized) return\n\n        val lens = lensView ?: return\n        val params = lensParams ?: return\n\n        minimizedView?.let { removeOverlay(it) }\n        minimizedView = null\n        minimizedParams = null\n\n        val restored = if (lens.isAttachedToWindow) {\n            true\n        } else {\n            runCatching {\n                windowManager.addView(lens, params)\n                true\n            }.getOrDefault(false)\n        }\n\n        if (!restored) {\n            // Keep the restore bubble available if reattaching the lens fails.\n            showMinimizedBubble()\n            return\n        }\n\n        magnifierMinimized = false\n        startRefreshing()\n        lens.post {\n            updateLensMatrix()\n            requestImmediateRefresh()\n        }\n    }\n\n'''
if marker not in text:
    raise SystemExit("Could not find navigation insertion point")
text = text.replace(marker, methods + marker, 1)

path.write_text(text, encoding="utf-8")
print("Added movable minimized screen magnifier bubble")
